using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround;

internal sealed class OriginalGaussianFiniteCandidateModesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite Original Gaussian Candidate Modes",
        H("Finite Original Gaussian Candidate Modes"),
        Blocks(
            Paragraph(Text("The actual positive source amplitude has finite support for every complex parameter: a(p,r)=sum n<=p centralWeight(n)*(-1)^n*choose(p,n)*r^n. Derivatives of a, the two denominator tables, and their finite convolutions use only finite sums. No parameter derivative is exchanged with an infinite sum over external modes.")),
            Paragraph(Text("The ++ candidate is t(p,q,r)=P(p,q,r)-k(r)*a(p,r)*a(q,r), composed with r=z squared. P contains both the r/2 convolution term and the direct r squared inverse-square contribution. The logarithmic period factor k=r*(1-r)*Fprime/F uses the literal original period and its existing Picard-Fuchs equation.")),
            Paragraph(Text("These are concrete finite mode functions with derivatives and analyticity on the unit disk. The inverse-table coefficient interpretation, candidate differential equations, actual nonzero negative-zero boundary, signed source extension, all J modes, and identification with original externalT remain separate obligations. The guarded shift11 is only a Taylor monomial shift; it never replaces the signed predecessor true,0 by zero.")),
            Describe.Lean(DescribeId.Create("sourceAmplitude-true-finite"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.sourceAmplitude_true_finite"), H("sourceAmplitude_true_finite"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Exact support reduction of the actual positive source to a finite polynomial."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hasDerivAt-L"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.hasDerivAt_L"), H("hasDerivAt_L"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The finite double convolution satisfies the full product rule for any scalar differentiable denominator table."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("ell-picard-fuchs"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.ell_picard_fuchs"), H("ell_picard_fuchs"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The existing period equation yields the exact logarithmic equation without dividing by r or 1-r."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hasDerivAt-k"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.hasDerivAt_k"), H("hasDerivAt_k"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The period factor has derivative 1/4-r*(1-r)*ell squared throughout the unit disk, including zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hasDerivAt-t"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.hasDerivAt_t"), H("hasDerivAt_t"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The complete finite candidate has the stated derivative, retaining its full polynomial contribution."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidateT-analyticOnNhd"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.candidateT_analyticOnNhd"), H("candidateT_analyticOnNhd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Each fixed positive mode candidate is analytic on the open unit disk in z."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hasDerivAt-candidateT"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.hasDerivAt_candidateT"), H("hasDerivAt_candidateT"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The z derivative is the finite r derivative times 2z."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidateT-even"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.candidateT_even"), H("candidateT_even"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The explicit z-squared composition is even."))), DescribeRole.Theorem))));
